window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c89058067c3ddadb"]={"versions": [{"id": "FIG-c89058067c3ddadb", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur ECU-Konfigurationsmetamodell-Definition (BSW-Modulbeschreibung) des Diagnostic Event Managers (Dem) im AUTOSAR-Standard. Es spezifiziert die hierarchische Container- und Parameterstruktur für die DTC-Gruppenkonfiguration innerhalb der Dem-Moduldefinition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Dem :EcucModuleDef</code> (Multiplizität <code>0..1</code>): Wurzelmoduldefinition des DEM.\n</li><li><code>DemGeneral :EcucParamConfContainerDef</code> (Multiplizität <code>1..1</code>): Allgemeiner Konfigurationscontainer, über die Kompositionsrolle <code>+container</code> unterhalb von <code>Dem</code> eingebettet.\n</li><li><code>DemGroupOfDTC :EcucParamConfContainerDef</code> (Multiplizität <code>0..255</code>): Konfigurationscontainer für DTC-Gruppen, über die Kompositionsrolle <code>+subContainer</code> dem Container <code>DemGeneral</code> untergeordnet.\n</li><li><code>DemGroupDTCs :EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter innerhalb von <code>DemGroupOfDTC</code>, angebunden über die Kompositionsrolle <code>+parameter</code>. Er besitzt die Attribute <code>min = 256</code>, <code>max = 16776959</code> (0x000100 bis 0xFFFFFF) und <code>symbolicNameValue = true</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurations-Metamodell definiert das Diagramm kein dynamisches Laufzeitverhalten und keine Sequenzabläufe. Es legt die deklarative Struktur und Schachtelung fest, nach der Werkzeuge DTC-Gruppen in der Generierungs- und Konfigurationsphase instanziieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration des DEM:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code> ist genau einmal je Dem-Modulkonfiguration vorzusehen (<code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 1</code>).\n</li><li>Es dürfen maximal 255 DTC-Gruppen (<code>DemGroupOfDTC</code>, <code>0..255</code>) definiert werden.\n</li><li>Jeder Gruppenparameter <code>DemGroupDTCs</code> muss als symbolischer Name (<code>symbolicNameValue = true</code>) im 24-Bit-DTC-Bereich zwischen 256 (0x000100) und 16776959 (0xFFFFFF) konfiguriert werden; Werte unter 256 sind ausgeschlossen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-10a660f1a2fe39c8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur ECU-Konfigurationsmetamodell-Definition (BSW-Modulbeschreibung) des Diagnostic Event Managers (Dem) im AUTOSAR-Standard. Es spezifiziert die hierarchische Container- und Parameterstruktur für die DTC-Gruppenkonfiguration innerhalb der Dem-Moduldefinition.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Entitäten und deren Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Dem :EcucModuleDef</code> (Multiplizität <code>0..1</code>): Wurzelmoduldefinition des DEM.\n</li><li><code>DemGeneral :EcucParamConfContainerDef</code> (Multiplizität <code>1..1</code>): Allgemeiner Konfigurationscontainer, über die Kompositionsrolle <code>+container</code> unterhalb von <code>Dem</code> eingebettet.\n</li><li><code>DemGroupOfDTC :EcucParamConfContainerDef</code> (Multiplizität <code>0..255</code>): Konfigurationscontainer für DTC-Gruppen, über die Kompositionsrolle <code>+subContainer</code> dem Container <code>DemGeneral</code> untergeordnet.\n</li><li><code>DemGroupDTCs :EcucIntegerParamDef</code>: Ganzzahliger Konfigurationsparameter innerhalb von <code>DemGroupOfDTC</code>, angebunden über die Kompositionsrolle <code>+parameter</code>. Er besitzt die Attribute <code>min = 256</code>, <code>max = 16776959</code> (0x000100 bis 0xFFFFFF) und <code>symbolicNameValue = true</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurations-Metamodell definiert das Diagramm kein dynamisches Laufzeitverhalten und keine Sequenzabläufe. Es legt die deklarative Struktur und Schachtelung fest, nach der Werkzeuge DTC-Gruppen in der Generierungs- und Konfigurationsphase instanziieren.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich für die Konfiguration des DEM:</p>\n<ul class=\"fig-list\"><li><code>DemGeneral</code> ist genau einmal je Dem-Modulkonfiguration vorzusehen (<code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 1</code>).\n</li><li>Es dürfen maximal 255 DTC-Gruppen (<code>DemGroupOfDTC</code>, <code>0..255</code>) definiert werden.\n</li><li>Jeder Gruppenparameter <code>DemGroupDTCs</code> muss als symbolischer Name (<code>symbolicNameValue = true</code>) im 24-Bit-DTC-Bereich zwischen 256 (0x000100) und 16776959 (0xFFFFFF) konfiguriert werden; Werte unter 256 sind ausgeschlossen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c89058067c3ddadb", "to": "FIG-10a660f1a2fe39c8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
